/**
 * React Example - Using CoolProp WASM in React Applications
 * 
 * This example shows different ways to use CoolProp in React:
 * 1. Simple PropsSI calculations
 * 2. React hooks for property calculations
 * 3. AbstractState management
 */

import React, { useState, useEffect } from 'react';
import { PropsSI, createAbstractState, useCoolProp, useProperty } from 'coolprop-wasm/simple';

// Example 1: Simple Property Calculator Component
function PropertyCalculator() {
    const [result, setResult] = useState(null);
    const [loading, setLoading] = useState(false);
    
    const calculateProperty = async () => {
        setLoading(true);
        try {
            // Calculate water density at 300K and 1 atm
            const density = await PropsSI('D', 'T', 300, 'P', 101325, 'Water');
            setResult(`Water density at 300K, 1 atm: ${density.toFixed(2)} kg/m³`);
        } catch (error) {
            setResult(`Error: ${error.message}`);
        }
        setLoading(false);
    };
    
    return (
        <div>
            <h3>Simple Property Calculator</h3>
            <button onClick={calculateProperty} disabled={loading}>
                {loading ? 'Calculating...' : 'Calculate Water Density'}
            </button>
            {result && <p>{result}</p>}
        </div>
    );
}

// Example 2: Interactive Property Calculator
function InteractiveCalculator() {
    const [temperature, setTemperature] = useState(300);
    const [pressure, setPressure] = useState(101325);
    const [fluid, setFluid] = useState('Water');
    const [property, setProperty] = useState('D');
    const [result, setResult] = useState(null);
    const [loading, setLoading] = useState(false);
    
    const calculate = async () => {
        setLoading(true);
        try {
            const value = await PropsSI(property, 'T', temperature, 'P', pressure, fluid);
            setResult(value);
        } catch (error) {
            setResult(`Error: ${error.message}`);
        }
        setLoading(false);
    };
    
    useEffect(() => {
        calculate();
    }, [temperature, pressure, fluid, property]);
    
    return (
        <div>
            <h3>Interactive Property Calculator</h3>
            <div>
                <label>
                    Temperature (K): 
                    <input 
                        type="number" 
                        value={temperature} 
                        onChange={(e) => setTemperature(Number(e.target.value))}
                    />
                </label>
            </div>
            <div>
                <label>
                    Pressure (Pa): 
                    <input 
                        type="number" 
                        value={pressure} 
                        onChange={(e) => setPressure(Number(e.target.value))}
                    />
                </label>
            </div>
            <div>
                <label>
                    Fluid: 
                    <select value={fluid} onChange={(e) => setFluid(e.target.value)}>
                        <option value="Water">Water</option>
                        <option value="CO2">CO2</option>
                        <option value="Nitrogen">Nitrogen</option>
                        <option value="Oxygen">Oxygen</option>
                    </select>
                </label>
            </div>
            <div>
                <label>
                    Property: 
                    <select value={property} onChange={(e) => setProperty(e.target.value)}>
                        <option value="D">Density (kg/m³)</option>
                        <option value="H">Enthalpy (J/kg)</option>
                        <option value="S">Entropy (J/kg/K)</option>
                        <option value="C">Heat Capacity (J/kg/K)</option>
                    </select>
                </label>
            </div>
            <div>
                <strong>Result: </strong>
                {loading ? 'Calculating...' : 
                 typeof result === 'number' ? result.toFixed(4) : result}
            </div>
        </div>
    );
}

// Example 3: Using React Hooks (if you include the react.js wrapper)
function HookBasedCalculator() {
    const { coolprop, isLoading, error } = useCoolProp();
    const { value: density, isLoading: densityLoading } = useProperty(
        'D', 'T', 300, 'P', 101325, 'Water'
    );
    
    if (isLoading) return <div>Loading CoolProp...</div>;
    if (error) return <div>Error loading CoolProp: {error.message}</div>;
    
    return (
        <div>
            <h3>Hook-Based Calculator</h3>
            <p>CoolProp loaded: ✅</p>
            <p>
                Water density at 300K, 1 atm: {' '}
                {densityLoading ? 'Calculating...' : 
                 density ? `${density.toFixed(2)} kg/m³` : 'Error'}
            </p>
        </div>
    );
}

// Example 4: Advanced AbstractState Usage
function AdvancedCalculator() {
    const [state, setState] = useState(null);
    const [properties, setProperties] = useState({});
    const [loading, setLoading] = useState(true);
    
    useEffect(() => {
        const initializeState = async () => {
            try {
                const abstractState = await createAbstractState('HEOS', 'Water');
                const coolprop = await getCoolProp();
                
                // Update to 300K, 1 atm
                abstractState.update(coolprop.input_pairs.PT_INPUTS, 101325, 300);
                
                // Get multiple properties
                const props = {
                    temperature: abstractState.T(),
                    pressure: abstractState.p(),
                    density: abstractState.rhomass(),
                    enthalpy: abstractState.hmass(),
                    entropy: abstractState.smass(),
                    heatCapacity: abstractState.cpmass()
                };
                
                setState(abstractState);
                setProperties(props);
            } catch (error) {
                console.error('Error initializing state:', error);
            }
            setLoading(false);
        };
        
        initializeState();
    }, []);
    
    if (loading) return <div>Initializing AbstractState...</div>;
    
    return (
        <div>
            <h3>Advanced AbstractState Calculator</h3>
            <p><strong>Water at 300K, 1 atm:</strong></p>
            <ul>
                <li>Temperature: {properties.temperature?.toFixed(2)} K</li>
                <li>Pressure: {(properties.pressure / 1000)?.toFixed(1)} kPa</li>
                <li>Density: {properties.density?.toFixed(2)} kg/m³</li>
                <li>Enthalpy: {(properties.enthalpy / 1000)?.toFixed(1)} kJ/kg</li>
                <li>Entropy: {(properties.entropy / 1000)?.toFixed(3)} kJ/kg/K</li>
                <li>Heat Capacity: {(properties.heatCapacity / 1000)?.toFixed(3)} kJ/kg/K</li>
            </ul>
        </div>
    );
}

// Main App Component
function App() {
    return (
        <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
            <h1>CoolProp WASM React Examples</h1>
            
            <PropertyCalculator />
            <hr />
            
            <InteractiveCalculator />
            <hr />
            
            <HookBasedCalculator />
            <hr />
            
            <AdvancedCalculator />
        </div>
    );
}

export default App;